import{z as u,x as E,o as d,c as p,q as s,j as r,D as e,d as t,s as n,S as o,b as i}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"auditd","description":"","frontmatter":{"title":"auditd","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kernel-audit.md","filePath":"cs/kernel-audit.md","lastUpdated":1791063341000}'),c={name:"cs/kernel-audit.md"};function B(A,a,m,f,h,D){const l=E("Mermaid");return d(),p("div",null,[a[2]||(a[2]=s('<h1 id="auditd" tabindex="-1">auditd <a class="header-anchor" href="#auditd" aria-label="Permalink to &quot;auditd&quot;">​</a></h1><div class="epigraph"><p>audit 子系统在钩子上生成记录：谁、何时、哪个系统调用、成功与否；auditd 在用户态写盘并轮转。</p><footer>—— 据 Linux audit 文档；[LSM](/cs/lsm-selinux) 拒绝路径；McKusick 对安全日志的背景</footer></div><p><a href="/cs/lsm-selinux">SELinux</a>/<a href="/cs/apparmor">AppArmor</a> 的拒绝需要 <strong>可问责</strong>。缺口是内核 audit + auditd，不是 syslog 的全部。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>规则：监视 <code>open</code> 某文件、cap 使用、exec。内核 <code>kauditd</code> 把记录送给用户 netlink。缺口：规则过多则 CPU 与丢事件；与 <a href="/cs/inotify">inotify</a> 不同——audit 是安全审计不是 IDE 热重载。本课不把每条 syscall 字段当作业。</p><p><span class="marginnote">immutable 标志可锁规则直到重启。容器要小心宿主机审计范围。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>auditctl</code> 下规则 → 系统调用返回路径发包 → auditd 写 <code>/var/log/audit</code>。对照 [fsnotify]：一个给桌面，一个给合规。对照 <a href="/cs/netfilter-conntrack">netfilter</a> 日志：对象不同。对照 printk 后课：dmesg 不是审计。</p>',8)),(d(),r(o,null,{default:e(()=>[n(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYS%5B%22syscall%2FLSM%22%5D%20--%3E%20KRULE%5B%22audit%20%E8%A7%84%E5%88%99%22%5D%0A%20%20KRULE%20--%3E%20NL%5B%22netlink%22%5D%0A%20%20NL%20--%3E%20AD%5B%22auditd%20%E8%90%BD%E7%9B%98%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[t("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,[t("audit 把内核决策变成不可轻易抵赖的序列（在磁盘与权限保护下）。它不阻止攻击，只留下痕迹。不要写成 SIEM 产品。与 "),i("a",{href:"/cs/fsync"},"fsync"),t("：日志完整性依赖刷盘策略。")],-1)),a[5]||(a[5]=i("p",null,"洪水：攻击者可用事件灌满，规则设计要有上限意识。",-1)),(d(),r(o,null,{default:e(()=>[n(l,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20EVT%5B%22%E8%A7%84%E5%88%99%E5%91%BD%E4%B8%AD%E7%9A%84%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20Q%5B%22backlog%20%E5%BE%85%E5%8F%91%E9%98%9F%E5%88%97%22%5D%0A%20%20Q%20--%3E%7C%22%E6%9C%89%E7%A9%BA%E9%97%B4%22%7C%20KD%5B%22kauditd%20%E5%8F%91%E9%80%81%22%5D%0A%20%20Q%20--%3E%7C%22%E9%98%9F%E5%88%97%E5%B7%B2%E6%BB%A1%22%7C%20DROP%5B%22%E4%B8%A2%E5%BC%83%E4%BA%8B%E4%BB%B6%E5%B9%B6%E8%AE%A1%E6%95%B0%22%5D%0A%20%20KD%20--%3E%20AD%5B%22auditd%20%E5%86%99%E7%9B%98%22%5D%0A%20%20AD%20--%3E%7C%22auditd%20%E5%8D%A1%E6%AD%BB%2F%E7%A3%81%E7%9B%98%E6%BB%A1%22%7C%20Q%0A%20%20DROP%20--%3E%20GAP%5B%22%E5%AE%A1%E8%AE%A1%E5%BA%8F%E5%88%97%E5%87%BA%E7%8E%B0%E7%BC%BA%E5%8F%A3%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">术语翻译：audit 和 auditd 是两件事——audit 是内核里生成记录的那一段，auditd 是用户态负责收下来、写盘、按大小轮转日志的守护进程；「d」后缀就是 daemon（守护进程）的惯例缩写。</span></p><p><span class="marginnote">数字实例：内核的 backlog 队列默认很小（常见配置如 8192 条，老默认只有 64 条）。一条 <code>open</code> 规则若盯着被高频访问的路径，每秒就能产生上万事件——几毫秒就能灌满队列，之后的事件直接丢弃。</span></p><p><span class="marginnote">常见误区：初学者容易把 audit 当入侵防御，实际上它一次也不会拦下攻击，只负责「记账」；价值在事后追责与取证。所以丢事件不是性能小瑕疵，而是审计链条上出现无法解释的缺口。</span></p><p>实现上：规则用 syscall 号和字段过滤，架构不同号不同。kauditd 拥塞会丢，不是可靠队列。immutable 后改规则要重启。 读法上只引用<a href="/cs/apparmor">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 内核安全与启动」课序里，对象是 <strong>auditd</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 arch 特定字段。不保证网络启动早期的 audit。下一课启动链：安全启动与签名。</p><p>版本字段会变，课序钉的是机制对象「auditd」，不是某一主线内核的结构体名。 后课默认：特权与 MAC 决策可被审计。固件验证内核签名，下一课安全启动。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>audit 在内核生成事件，auditd 落盘。</li><li>与 inotify 目标不同；过量规则会丢。</li><li>安全启动是下一课。</li><li>出处：Linux audit；auditd；LSM。</li></ul>',11))])}const b=u(c,[["render",B]]);export{_ as __pageData,b as default};
